def transform(grid):
    h, w = len(grid), len(grid[0])
    color = next((v for row in grid for v in row if v), 0)
    # Each occupied cell expands to a 3x3 copy of the complement of the
    # occupied-cell pattern in the input.
    motif = [[color if not grid[r][c] else 0 for c in range(w)] for r in range(h)]
    out = [[0 for _ in range(3*w)] for _ in range(3*h)]
    for r in range(h):
        for c in range(w):
            if grid[r][c]:
                for dr in range(h):
                    for dc in range(w):
